drop policy if exists clients_insert_onboarding on public.clients; create policy clients_insert_onboarding on public.clients for insert to authenticated with check ((select public.iberfit_role()) in ('admin'::public.iberfit_role,'coach'::public.iberfit_role)); drop policy if exists client_intake_insert_onboarding on public.client_intake_profiles; create policy client_intake_insert_onboarding on public.client_intake_profiles for insert to authenticated with check ((select public.iberfit_role()) in ('admin'::public.iberfit_role,'coach'::public.iberfit_role) and created_by=(select auth.uid()) and updated_by=(select auth.uid())); drop policy if exists profiles_insert_onboarding on public.client_app_profiles; create policy profiles_insert_onboarding on public.client_app_profiles for insert to authenticated with check ((select public.iberfit_role()) in ('admin'::public.iberfit_role,'coach'::public.iberfit_role) and created_by=(select auth.uid())); drop policy if exists assignments_insert_onboarding on public.client_assignments; create policy assignments_insert_onboarding on public.client_assignments for insert to authenticated with check ((select public.iberfit_role())='admin'::public.iberfit_role or ((select public.iberfit_role())='coach'::public.iberfit_role and coach_user_id=(select auth.uid()))); drop policy if exists timeline_insert_onboarding_coach on public.client_timeline_events; create policy timeline_insert_onboarding_coach on public.client_timeline_events for insert to authenticated with check ((select public.iberfit_role())='coach'::public.iberfit_role and public.is_assigned_coach(client_id)); alter function public.iberfit_create_client_draft(jsonb) security invoker;;
